(let [held (:seon.store/store (#'boot/selected-instance "default")) prefix (str "astra-loaded-files-" (id/id)) branches (mapv #(keyword (str prefix %)) ["-publication" "-adoption"])] (doseq [b branches] (registry/branch! {:seon.store/store held :seon.store/branch b :seon.cluster.registry/from :cluster-default})) (let [[published adopted :as connections] (mapv #(store/open-branch! held %) branches)] (try (let [row ((fn [database sym text] (let [projection (db/carried-projection database) ns-row (#'support/digest-namespace-entity database (symbol (namespace sym))) rows (source-rows-after database (program/shapes-in projection) ns-row text (set (keys (:seon.schema.projection/forms projection)))) row (some #(when (= sym (:seon.fn/sym %)) %) rows)] (#'support/revised-entity database (index/contract-facts-row projection ns-row row) {} ns-row))) (db/db published) 'seon.cluster/loaded-files "(defn- loaded-files\n  \"The bytes the code this JVM runs came from, which a publication's seal reads\n  its entities through (`selected-analyzer-digest`): the files the commit its\n  last adoption loaded publishes (`sci.eval/loaded-identity`); before any\n  adoption, the files launch loaded; none when the loaded program is unknown\n  (an adoption failed mid-reload) or the adopted commit is another store's (a\n  fixture's root), so every reached declaration names another analyzer.\n\n  Costs: one indexed read of the adopted commit's file digests; no projection\n  and no program-wide read.\"\n  {:malli/schema [:=> [:cat :seon.store/store] :seon.source/relative-file-digests]}\n  [store]\n  (let [loaded @sci.eval/loaded-identity\n        adopted (:seon.source/commit-id loaded)]\n    (cond\n      (not adopted) (if (seq loaded) {} launched-source-digests)\n      :else\n      (if-let [database (source/commit-database store adopted)]\n        (try\n          (into {} (d/q '[:find ?path ?digest\n                          :where [?file :seon.fn.file/relative-path ?path]\n                                 [?file :seon.fn.file/digest ?digest]]\n                        database))\n          (finally (d/release-materialized-db database)))\n        {}))))") report (db/call-with-custody {:seon.db/connection published} #(db/transact! published [row]))] (when-not (:db-after report) (throw (ex-info "Publication refused" report))) (let [source (db/db published) projection (db/carried-projection source) identities #{[:seon.fn/sym 'seon.cluster/loaded-files]} result (db/call-with-custody {:seon.db/connection adopted} #(schema/call-with-projection projection (fn [] (index-after! {:seon.db/connection adopted :seon.source/database source :seon.reconcile/adopt-identities identities}))))] (assert (:seon.db/transaction-report result)) (assert (= (index/published-index-entities source (vec identities)) (index/published-index-entities (db/db adopted) (vec identities)))) {:published? true :adopted? true :operations (:seon.reconcile/operations result)})) (finally (doseq [c connections] (store/release-branch! c)) (doseq [b branches] (registry/retire-branch! {:seon.store/store held :seon.store/branch b}))))))
